--
-- Structure for view `active_subscriptions`
--
DROP TABLE IF EXISTS `active_subscriptions`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `active_subscriptions`  AS SELECT `b`.`id` AS `branch_id`, `b`.`name` AS `branch_name`, `b`.`school_name` AS `school_name`, `sp`.`id` AS `plan_id`, `sp`.`name` AS `plan_name`, `sp`.`price_monthly` AS `price_monthly`, `sp`.`price_termly` AS `price_termly`, `sp`.`price_yearly` AS `price_yearly`, `bs`.`billing_cycle` AS `billing_cycle`, `bs`.`start_date` AS `start_date`, `bs`.`end_date` AS `end_date`, `bs`.`next_billing_date` AS `next_billing_date`, `bs`.`status` AS `subscription_status`, to_days(`bs`.`end_date`) - to_days(curdate()) AS `days_remaining`, CASE WHEN `bs`.`end_date` < curdate() THEN 'Expired' WHEN `bs`.`end_date` <= curdate() + interval 7 day THEN 'Expiring Soon' ELSE 'Active' END AS `expiry_status`, `sc`.`credits` AS `current_sms_credits`, `sc`.`monthly_allowance` AS `monthly_allowance`, `sc`.`carry_forward` AS `carry_forward`, `sc`.`credits`+ `sc`.`carry_forward` AS `total_available_sms` FROM (((`branch` `b` join `branch_subscriptions` `bs` on(`b`.`subscription_id` = `bs`.`id`)) join `subscription_plans` `sp` on(`bs`.`plan_id` = `sp`.`id`)) left join `sms_credit` `sc` on(`b`.`id` = `sc`.`branch_id`)) WHERE `bs`.`status` = 'active' ;

-- --------------------------------------------------------

--
-- Structure for view `module_usage_summary`
--
DROP TABLE IF EXISTS `module_usage_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `module_usage_summary`  AS SELECT `module_usage`.`branch_id` AS `branch_id`, `module_usage`.`module_id` AS `module_id`, `module_usage`.`billing_month` AS `billing_month`, `module_usage`.`action` AS `action`, sum(`module_usage`.`quantity`) AS `total_quantity`, count(distinct `module_usage`.`reference_id`) AS `unique_actions`, count(0) AS `usage_count`, max(`module_usage`.`created_at`) AS `last_used` FROM `module_usage` GROUP BY `module_usage`.`branch_id`, `module_usage`.`module_id`, `module_usage`.`billing_month`, `module_usage`.`action` ;

-- --------------------------------------------------------

--
-- Structure for view `sms_usage_summary`
--
DROP TABLE IF EXISTS `sms_usage_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `sms_usage_summary`  AS SELECT `module_usage`.`branch_id` AS `branch_id`, `module_usage`.`billing_month` AS `billing_month`, sum(case when `module_usage`.`action` = 'sms_sent' then `module_usage`.`quantity` else 0 end) AS `sms_sent`, sum(case when `module_usage`.`action` = 'sms_purchased' then `module_usage`.`quantity` else 0 end) AS `sms_purchased`, sum(case when `module_usage`.`action` = 'sms_sent' then `module_usage`.`quantity` else 0 end) - sum(case when `module_usage`.`action` = 'sms_purchased' then `module_usage`.`quantity` else 0 end) AS `net_usage`, count(distinct case when `module_usage`.`action` = 'sms_sent' then `module_usage`.`reference_id` end) AS `campaigns_count` FROM `module_usage` WHERE `module_usage`.`module_id` = (select `permission_modules`.`id` from `permission_modules` where `permission_modules`.`prefix` = 'bulk_sms_and_email') GROUP BY `module_usage`.`branch_id`, `module_usage`.`billing_month` ;

